begin;
create temporary table mobilization_test_context as select gen_random_uuid() coordinator,gen_random_uuid() articulator,gen_random_uuid() other_articulator,gen_random_uuid() educator,gen_random_uuid() request;
grant select on mobilization_test_context to authenticated;
insert into auth.users(id,email) select x,x::text||'@mobilization-test.invalid' from mobilization_test_context cross join lateral unnest(array[coordinator,articulator,other_articulator,educator]) x;
update public.profiles set role='coordenacao_articulacao',active=true,display_name='TESTE MOB COORD' where id=(select coordinator from mobilization_test_context);
update public.profiles set role='articulador',active=true,display_name='TESTE MOB ART' where id in(select articulator from mobilization_test_context union select other_articulator from mobilization_test_context);
update public.profiles set role='educador',active=true,display_name='TESTE MOB EDU' where id=(select educator from mobilization_test_context);
insert into public.articulation_mobilization_requests(id,source_type,source_title,requested_by,planned_date,status) select request,'oficina','__TESTE_MOBILIZACAO__',educator,'2027-03-20','solicitado' from mobilization_test_context;
insert into public.articulation_mobilization_plans(request_id,articulator_user_id,mobilization_goal,strategies,territories,mobilization_deadline,status) select request,articulator,'Objetivo de teste',array['WhatsApp'],array['Território teste'],'2027-03-19','planejado' from mobilization_test_context;
select set_config('request.jwt.claim.sub',(select coordinator::text from mobilization_test_context),true);
set local role authenticated;
do $test$
declare c record;s record;m record;a record;result jsonb;denied boolean:=false;ver uuid;
begin
 select * into c from mobilization_test_context;
 perform public.mobilization_command('import','{"month":"2027-03-01"}');
 perform public.mobilization_command('import','{"month":"2027-03-01"}');
 if (select count(*) from public.articulation_mobilization_strategies where c.request=any(request_ids))<>1 then raise exception 'Importação duplicou proposta';end if;
 select * into s from public.articulation_mobilization_strategies where c.request=any(request_ids);
 perform set_config('request.jwt.claim.sub',c.articulator::text,true);
 begin perform public.mobilization_command('review',jsonb_build_object('id',s.id,'expected_revision',s.revision,'review_status','approved'));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Articulador aprovou estratégia';end if;
 perform set_config('request.jwt.claim.sub',c.other_articulator::text,true);denied:=false;
 begin perform public.mobilization_command('save_strategy',jsonb_build_object('id',s.id,'expected_revision',s.revision,'title','Intrusão','review_status','submitted'));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Outro articulador editou a proposta';end if;
 perform set_config('request.jwt.claim.sub',c.coordinator::text,true);
 result:=public.mobilization_command('review',jsonb_build_object('id',s.id,'expected_revision',s.revision,'review_status','approved'));
 denied:=false;
 begin perform public.mobilization_command('review',jsonb_build_object('id',s.id,'expected_revision',s.revision,'review_status','approved'));exception when serialization_failure then denied:=true;end;
 if not denied then raise exception 'Aceitou aprovação sobre revisão antiga';end if;
 perform public.mobilization_command('save_month','{"reference_month":"2027-03-01","title":"__TESTE_MOBILIZACAO__","objective":"Objetivo geral"}');
 select * into m from public.articulation_monthly_mobilization_plans where reference_month='2027-03-01';
 denied:=false;
 begin perform public.mobilization_command('publish',jsonb_build_object('id',m.id,'expected_revision',m.revision));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'Publicou plano sem ações';end if;
 result:=public.mobilization_command('save_action',jsonb_build_object('monthly_plan_id',m.id,'plan_revision',m.revision,'title','Mobilização WhatsApp','action_type','Mobilização','channel','WhatsApp','location','CRJ','scheduled_date','2027-03-16','start_time','14:00','end_time','15:00','reference_user_id',c.articulator,'collaborator_ids',jsonb_build_array(c.educator),'strategy_ids',jsonb_build_array(s.id),'request_ids',jsonb_build_array(c.request),'objective','Objetivo','preparation_steps','1. Preparar mensagem e material','execution_steps','2. Contatar os jovens','resources','Celular e internet','documents_before','Material de divulgação','documents_after','Relatório e interesse','preparation_deadline','2027-03-15'));
 select * into m from public.articulation_monthly_mobilization_plans where id=m.id;
 result:=public.mobilization_command('publish',jsonb_build_object('id',m.id,'expected_revision',m.revision));ver:=(result->'version'->>'id')::uuid;
 if result->'version'->>'submission_id' is null then raise exception 'Evidência não gerada';end if;
 if (result->'version'->'snapshot'->'actions'->0->>'resources')<>'Celular e internet' then raise exception 'Snapshot perdeu recursos';end if;
 if (select public.mobilization_command('evidence',jsonb_build_object('id',m.id,'expected_revision',m.revision))->'version'->>'id')<>ver::text then raise exception 'Gerou evidência duplicada da mesma revisão';end if;
 select * into a from public.articulation_mobilization_actions where monthly_plan_id=m.id;
 perform set_config('request.jwt.claim.sub',c.other_articulator::text,true);denied:=false;
 begin perform public.mobilization_command('complete',jsonb_build_object('action_id',a.id));exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Não participante confirmou execução';end if;
 perform set_config('request.jwt.claim.sub',c.articulator::text,true);
 result:=public.mobilization_command('complete',jsonb_build_object('action_id',a.id));
 if result->'execution'->>'completed'<>'true' then raise exception 'Não confirmou execução';end if;
 result:=public.mobilization_command('report',jsonb_build_object('action_id',a.id,'expected_revision',(result->'execution'->>'revision')::int,'action_name','Ação realizada','executed_date','2027-03-16','location','CRJ','mobilization_type','WhatsApp','positives','Boa adesão','negatives','Sem dificuldade','observations','Teste','report_status','finalized'));
 if not exists(select 1 from public.methodology_form_submissions where source_type='articulation_mobilization_executions' and source_id=(result->'execution'->>'id')::uuid) then raise exception 'Relatório sem evidência';end if;
 result:=public.mobilization_command('register_interest',jsonb_build_object('action_id',a.id,'form',jsonb_build_object('full_name','__TESTE_JOVEM_MOB_'||c.request::text,'birth_date','2008-01-01','phone','27999990000','desired_workshop','Oficina de teste')));
 if result->>'young_person_id' is null then raise exception 'Não gerou cadastro provisório';end if;
 if not exists(select 1 from public.articulation_mobilization_interests where action_id=a.id and young_person_id=(result->>'young_person_id')::uuid) then raise exception 'Não vinculou banco de interesses';end if;
 if (select initial_form_status from public.young_people where id=(result->>'young_person_id')::uuid)<>'provisorio' then raise exception 'Novo jovem não está provisório';end if;
 result:=public.mobilization_command('register_interest',jsonb_build_object('action_id',a.id,'young_person_id',result->>'young_person_id','form',jsonb_build_object('desired_workshop','Oficina de teste')));
 if result->>'already_registered'<>'true' then raise exception 'Repetição duplicou o interesse';end if;
 perform set_config('request.jwt.claim.sub',c.educator::text,true);denied:=false;
 if (select count(*) from public.articulation_mobilization_interests)<>0 then raise exception 'Educador acessou o banco de interesses';end if;
 begin perform public.mobilization_command('save_month','{"reference_month":"2027-04-01","title":"Intrusão"}');exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Educador editou plano da coordenação';end if;
 perform set_config('request.jwt.claim.sub',c.coordinator::text,true);denied:=false;
 begin perform public.mobilization_command('cancel_action',jsonb_build_object('id',a.id,'expected_revision',a.revision,'reason','Teste'));exception when raise_exception then denied:=true;end;
 if not denied then raise exception 'Cancelou ação com execução ou interesse';end if;
 update public.articulation_mobilization_plans set mobilization_goal='Objetivo revisto na origem' where request_id=c.request;
 if (select status from public.articulation_monthly_mobilization_plans where id=m.id)<>'draft' then raise exception 'Edição da origem não reabriu revisão';end if;
 if not exists(select 1 from public.articulation_mobilization_strategies where id=s.id and source_changed) then raise exception 'Edição da origem não sinalizada';end if;
 if (select snapshot->'actions'->0->>'objective' from public.articulation_mobilization_plan_versions where id=ver)<>'Objetivo' then raise exception 'Edição alterou evidência anterior';end if;
end $test$;
rollback;
